  // Fold the right ear forward, bending its blush inset with the cream shell.
  function foldRightEar(mesh) {
    mesh.updateMatrix();
    const inverse = mesh.matrix.clone().invert();
    const vertex = new THREE.Vector3();
    const positions = mesh.geometry.attributes.position;
    const hingeY = 2.87, hingeZ = .47, radius = .18;
    for (let i = 0; i < positions.count; i++) {
      vertex.fromBufferAttribute(positions, i).applyMatrix4(mesh.matrix);
      const height = vertex.y - hingeY;
      if (height > 0) {
        const angle = height / radius;
        const depth = vertex.z - hingeZ;
        vertex.y = hingeY + Math.sin(angle) * (radius - depth);
        vertex.z = hingeZ + radius * (1 - Math.cos(angle)) + depth * Math.cos(angle);
      }
      vertex.applyMatrix4(inverse);
      positions.setXYZ(i, vertex.x, vertex.y, vertex.z);
    }
    positions.needsUpdate = true;
    mesh.geometry.computeVertexNormals();
    mesh.geometry.computeBoundingBox();
    mesh.geometry.computeBoundingSphere();
  }
